/** Explicit local-only recipe rehearsal. Imports perform no IO, authentication or writes. */
import {open,readFile} from 'node:fs/promises'
import {resolve,relative,dirname} from 'node:path'
import {createPostgresConnection,HostedWorkspaceDatabase,readMigrationManifest,type WorkspaceConnection} from '../../packages/neuvetra-database/src/index'
import {m78CanonicalJson as canonical,parseM78Json} from '../../packages/neuvetra-database/src/m78-validation'
import {M78_REVIEWED_POLICY} from '../../packages/neuvetra-database/src/m78-policy'
import {m78FixtureAuthorities} from './m78-backend-fixture'
