const COMPANY='8b90c706-1710-494d-b12d-02eef88eacb7',PROJECT='icockcoguyadhryzydvl',ORIGIN='http://127.0.0.1:4198',PROFILE='m78-local-exact-recipe-rehearsal-v1'
const uuid=/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/,digest=/^[a-f0-9]{64}$/
const sha=(v:string|Uint8Array)=>new Bun.CryptoHasher('sha256').update(v).digest('hex'),same=(a:unknown,b:unknown)=>canonical(a)===canonical(b)
function check(value:unknown,message:string):asserts value{if(!value)throw Error(message)}
export interface M78RecipeVersionRecord {id:string;version:number;review?:unknown;streamId?:string;worksheetId?:string;rosterId?:string;inventoryId?:string}
/** Called only after the family decoder: legacy records have a numeric version, M78 wraps a version record. */
export function m78RecipeVersionRecord(decoded:unknown):M78RecipeVersionRecord{
 const outer=decoded as {version?:unknown}|null;
 check(outer&&typeof outer==='object','Decoded version record required.');
 const version=(typeof outer.version==='number'?outer:outer.version) as M78RecipeVersionRecord|null;
 check(version&&typeof version==='object'&&uuid.test(version.id)&&Number.isInteger(version.version)&&version.version>0,'Decoded version identity required.');
 return version;
}
/** Fleet/equipment reviews live in decoded register.reviews; all other families embed the review on the version. */
export function m78RecipeRetainedReview(decoded:unknown,versionId:string,reviewId:string):unknown{
 check(uuid.test(versionId)&&uuid.test(reviewId),'Exact review identity required.');
 const register=decoded as {reviews?:unknown};
 if(Array.isArray(register?.reviews)){
  const matches=register.reviews.filter((r:any)=>r?.versionId===versionId&&r?.id===reviewId);
  check(matches.length===1,'Exact retained roster review missing or duplicated.');return matches[0];
 }
 const version=m78RecipeVersionRecord(decoded),review=version.review as {versionId?:string;id?:string}|null;
 check(version.id===versionId&&review?.versionId===versionId&&review.id===reviewId,'Exact retained version review missing.');return review;
}
type Role='manager1'|'manager2'|'member'
type Pin={path:string;sha256:string}
export interface M78RecipeInput {mode:'inspect'|'run';database:string;companyId:string;actorIds:Record<Role,string>;migrationSha256:string;recipeSha256:string;runnerSha256:string;reviewedSourcePins:Pin[];provenancePins:Pin[];baselineRowsSha256:string;journalPath:string}
export function parseM78RecipeInput(v:unknown):M78RecipeInput{const r=v as M78RecipeInput;check(r&&['inspect','run'].includes(r.mode)&&/^m78_ops_recipe_[a-z0-9_]+$/.test(r.database)&&r.companyId===COMPANY,'Fixed fresh recipe database/company required.');check(r.actorIds&&Object.keys(r.actorIds).sort().join(',')==='manager1,manager2,member'&&Object.values(r.actorIds).every(id=>uuid.test(id))&&new Set(Object.values(r.actorIds)).size===3,'Three distinct retained actor IDs required.');for(const key of ['migrationSha256','recipeSha256','runnerSha256']as const)check(digest.test(r[key]),'Exact reviewed source hashes required.');if(r.mode==='run'){check(digest.test(r.baselineRowsSha256)&&Array.isArray(r.reviewedSourcePins)&&r.reviewedSourcePins.length>3,'Reviewed source closure and baseline required.');check(Array.isArray(r.provenancePins)&&r.provenancePins.length>=3&&r.provenancePins.every(p=>typeof p.path==='string'&&digest.test(p.sha256))&&new Set(r.provenancePins.map(p=>p.path)).size===r.provenancePins.length,'Reviewed backup/restore/upgrade provenance pins required.');const local=relative(resolve('.'),resolve(r.journalPath)).replaceAll('\\','/');check(/^(\.superpowers|\.tmp)\/m78-recipe-[a-z0-9_-]+\.jsonl$/.test(local),'New bounded workspace journal path required.');}return r}
export const M78_RECIPE_RESOLVER_PINS=['package.json','tsconfig.base.json','packages/neuvetra-database/package.json','packages/neuvetra-database/tsconfig.json','apps/site-api/package.json','apps/site-api/tsconfig.json','config/typescript/api.json','apps/site-web/package.json','apps/site-web/tsconfig.json','apps/site-web/tsconfig.app.json','apps/site-web/tsconfig.node.json','config/typescript/web.json','config/typescript/vite.json']as const;
export async function m78RecipeSourcePins(){const files=new Set(['tools/staging/m78-recipe-rehearsal.ts','bun.lock',...M78_RECIPE_RESOLVER_PINS]),pending=['tools/staging/m78-recipe-rehearsal.ts'];while(pending.length){const file=pending.pop()!,text=await readFile(file,'utf8');for(const match of text.matchAll(/\b(?:from\s*|import\s*\(\s*|import\s*)['"]([^'"]+)['"]/g)){const name=match[1]!;if(!name.startsWith('.'))continue;const base=resolve(dirname(file),name);let target:string|undefined;for(const p of [base,base+'.ts',base+'.tsx',resolve(base,'index.ts')]){try{await readFile(p);target=p;break}catch{}}check(target,'Unresolved rehearsal import.');const path=relative(resolve('.'),target).replaceAll('\\','/');check(!path.startsWith('../')&&!path.startsWith('/')&&!path.includes(':'),'Rehearsal import outside workspace.');if(!files.has(path)){files.add(path);if(/\.tsx?$/.test(path))pending.push(path)}}}for(const m of await readMigrationManifest())files.add('packages/neuvetra-database/src/migrations/'+m.name);return Promise.all([...files].sort().map(async path=>({path,sha256:sha(await readFile(path))})))}
const FAMILIES=['corporate_inventory','stationary_gas','mobile_diesel','controlled_fleet','stationary_diesel','stationary_equipment','fugitive','scope1']
const HEADS=new Set(FAMILIES.map(f=>f+'_heads'))
type Rows=Record<string,string[]>
export async function m78RecipeRows(c:WorkspaceConnection):Promise<Rows>{const tables=(await c.query<{name:string}>("select table_name name from information_schema.tables where table_schema='neuvetra' and table_type='BASE TABLE' order by table_name")).rows,out:Rows={};for(const {name}of tables){check(/^[a-z0-9_]+$/.test(name),'Unsafe table.');out[name]=(await c.query<{row:string}>(`select neuvetra.m67_canonical(to_jsonb(t))row from neuvetra.${name} t order by neuvetra.m67_canonical(to_jsonb(t)) collate "C"`)).rows.map(r=>r.row)}return out}
const normalizeHead=(name:string,row:string)=>{const v=JSON.parse(row);if(HEADS.has(name)&&v.company_id===COMPANY){delete v.version_id;delete v.revision}return canonical(v)}
export function verifyM78RecipeOldRows(before:Rows,after:Rows){check(same(Object.keys(before),Object.keys(after)),'Table set changed.');let retained=0;for(const name of Object.keys(before)){const append=FAMILIES.some(f=>name.startsWith(f+'_')),old=before[name]!,current=after[name]!,counts=new Map<string,number>();for(const row of current){const key=normalizeHead(name,row);counts.set(key,(counts.get(key)??0)+1)}for(const row of old){const key=normalizeHead(name,row),count=counts.get(key)??0;check(count>0,'Old row changed or removed: '+name);counts.set(key,count-1);retained++}if(!append)check(same(old,current),'Unrelated rows appended: '+name);if(HEADS.has(name)&&name!=='scope1_heads')check(old.length===current.length,'Legacy heads added.');if(append)for(const [row,count]of counts)if(count>0)check(JSON.parse(row).company_id===COMPANY,'Other tenant row added.')}return {retainedOldRows:retained,tableCount:Object.keys(before).length,headException:'only target-company version_id/revision; all other old head fields retained',requestException:'none: every old request row retained; new fixed-recipe rows allowed'}}
async function roles(c:WorkspaceConnection){return(await c.query("select jsonb_build_object('roles',(select jsonb_agg(to_jsonb(r)order by rolname)from pg_roles r),'memberships',(select jsonb_agg(to_jsonb(m)order by roleid,member,grantor)from pg_auth_members m))body")).rows[0]!.body}
export async function runM78Recipe(input:M78RecipeInput){const operator=createPostgresConnection(`postgres://supabase_admin@127.0.0.1:55472/${input.database}`,{tls:false,maxConnections:1});let runtime:WorkspaceConnection|undefined,journal:Awaited<ReturnType<typeof open>>|undefined;let sequence=0,previousSha256:string|null=null,journalBytes=0,posts=0,stage='preconditions';
const append=async(kind:string,data:unknown)=>{check(journal,'Exclusive journal missing.');const body={profile:PROFILE,sequence:++sequence,previousSha256,kind,data,createdAt:new Date().toISOString()},hash=sha(canonical(body)),line=JSON.stringify({...body,sha256:hash})+'\n',bytes=Buffer.byteLength(line);check(bytes<=50_000_000&&journalBytes+bytes<=128_000_000,'Recipe journal capacity exceeded.');await journal.writeFile(line);await journal.sync();previousSha256=hash;journalBytes+=bytes};
try{const target=(await operator.query<{database:string;username:string;host:string;port:number}>('select current_database()database,current_user username,host(inet_server_addr())host,inet_server_port()port')).rows[0]!;check(target.database===input.database&&target.username==='supabase_admin'&&target.port===55472&&['127.0.0.1','::1'].includes(target.host),'Native local target refused.');const manifest=await readMigrationManifest(),receipts=(await operator.query<{name:string;sha256:string}>('select name,sha256 from neuvetra.schema_migrations order by name')).rows;check(manifest.length===21&&same(receipts,manifest.map(({name,sha256})=>({name,sha256})))&&manifest[20]!.sha256===input.migrationSha256,'Exact21 receipts required.');check(sha(await readFile('tools/staging/m78-hosted-plan.ts'))===input.recipeSha256&&sha(await readFile('tools/staging/m78-recipe-rehearsal.ts'))===input.runnerSha256,'Reviewed runner/recipe changed.');const sourcePins=await m78RecipeSourcePins();if(input.mode==='run'){check(same(sourcePins,input.reviewedSourcePins),'Complete reviewed rehearsal source closure changed.');for(const pin of input.provenancePins){const local=relative(resolve('.'),resolve(pin.path)).replaceAll('\\','/');check(!local.startsWith('../')&&!local.startsWith('/')&&!local.includes(':'),'Provenance outside workspace.');check(sha(await readFile(pin.path))===pin.sha256,'Reviewed backup/restore/upgrade provenance changed.');}}const targetProfile=(await operator.query<{project_ref:string;profile:string}>('select project_ref,profile from neuvetra.staging_target')).rows;check(targetProfile.length===1&&targetProfile[0]!.project_ref===PROJECT&&targetProfile[0]!.profile==='neuvetra.private-synthetic-staging.v1','Fixed synthetic project required.');const before=await m78RecipeRows(operator),baselineRowsSha256=sha(canonical(before)),beforeRoles=await roles(operator);
runtime=createPostgresConnection(`postgres://neuvetra_runtime@127.0.0.1:55472/${input.database}`,{tls:false,maxConnections:3});const database=new (HostedWorkspaceDatabase as any)(runtime,PROJECT) as HostedWorkspaceDatabase,authorities=m78FixtureAuthorities(),baseline=await database.findScope1(input.actorIds.manager1,COMPANY,authorities,M78_REVIEWED_POLICY);check(baseline&&baseline.coverageVersion.synthetic&&baseline.process.versions.length===0&&baseline.inventory.versions.length===0,'Empty M78 synthetic baseline required.');check(baseline.coverageVersion.createdBy===input.actorIds.manager1,'Manager1 must match retained corporate creator.');const members=(await operator.query<{user_id:string;role:string}>('select user_id,role from neuvetra.company_members where company_id=$1',[COMPANY])).rows;for(const role of ['manager1','manager2','member']as const)check(members.some(m=>m.user_id===input.actorIds[role]&&(role==='member'?m.role==='member':['owner','admin'].includes(m.role))),'Retained company role mismatch.');for(const v of [baseline.coverageVersion,...baseline.proof.sourceVersions.map(s=>s.version),...(['fleet','stationary','fugitive']as const).map(f=>baseline.proof[f].version).filter(v=>v!==null)])check(!v.contributorIds.includes(input.actorIds.manager2),'Configured manager2 is a retained contributor.');check(baseline.coverageVersion.version===8&&baseline.proof.fugitive.version?.version===4&&baseline.proof.fugitive.review?.decision==='accepted_bounded_reconciliation','Actual accepted final M77 continuation baseline required; failed-state template refused.');check((await operator.query<{count:string}>("select count(*)::text count from neuvetra.fugitive_reports where company_id=$1",[COMPANY])).rows[0]!.count==='9','Exact retained nine M77 reports required.');check(baseline.coverageVersion.snapshot.entities.length===2&&baseline.coverageVersion.snapshot.facilities.length===3&&baseline.proof.sourceVersions.length===10,'Actual graph must match fixed recipe.');
if(input.mode==='run')check((await operator.query<{locked:boolean}>('select pg_try_advisory_lock(780038)locked')).rows[0]!.locked,'Another recipe rehearsal owns this clone.');if(input.mode==='inspect')return {status:'m78_recipe_readonly_inspected',database:input.database,companyId:COMPANY,actorIds:input.actorIds,sourcePins,baselineRowsSha256,tableCount:Object.keys(before).length,applicationPostRequests:0,sourceShape:{corporateVersion:baseline.coverageVersion.version,entities:2,facilities:3,currentSources:10,fugitivePopulationVersion:baseline.proof.fugitive.version?.version},profile:'local_restored_actual_application_clone; providerAuth not used'};
check(input.baselineRowsSha256===baselineRowsSha256,'Actual restored baseline rows changed.');journal=await open(resolve(input.journalPath),'wx',0o600);await append('baseline',{input,receipts,sourcePins,baselineRowsSha256,oldRows:before,baseline,rolesSha256:sha(canonical(beforeRoles)),authentication:'fixed synthetic local role mapping; no provider sessions'});
const tokens=Object.fromEntries(Object.entries(input.actorIds).map(([role,id])=>['synthetic-recipe-'+role,id])),validateUser=async(token:string)=>tokens[token]?{id:tokens[token],phone:null,email:null,fullName:null}:null,deps={database,validateUser,origin:ORIGIN},handlers:{[path:string]:(r:Request)=>Promise<Response>}={'corporate-inventories':createCorporateInventoryRoutes(deps),'stationary-natural-gas':createM73Routes({...deps,authority:authorities.gas}),'mobile-diesel':createM74Routes({...deps,authority:authorities.mobile}),'controlled-fleet':createM75Routes({...deps,authority:authorities.mobile}),'stationary-equipment':createM76Routes({...deps,authorities:{gas:authorities.gas,diesel:authorities.diesel}}),'stationary-diesel':createM76Routes({...deps,authorities:{gas:authorities.gas,diesel:authorities.diesel}}),'fugitive-sources':createM77Routes({...deps,authority:authorities.fugitive}),'fugitive-population':createM77Routes({...deps,authority:authorities.fugitive}),'process-screen':createM78Routes({...deps,authorities,policy:M78_REVIEWED_POLICY}),'scope1-inventory':createM78Routes({...deps,authorities,policy:M78_REVIEWED_POLICY})},root='/workspace-api/workspace/'+COMPANY;
const call=async(route:string,role:Role,request?:unknown)=>{check(route.startsWith(root+'/')&&!route.includes('?')&&!route.includes('#'),'Fixed local route required.');const path=route.slice('/workspace-api'.length),family=path.split('/')[3]!,handler=handlers[family];check(handler,'Unmapped native route.');const response=await handler(new Request('http://127.0.0.1:4199'+path,{method:request===undefined?'GET':'POST',headers:{origin:ORIGIN,authorization:'Bearer synthetic-recipe-'+role,'content-type':'application/json'},body:request===undefined?undefined:JSON.stringify(request)}));const bytes=new Uint8Array(await response.arrayBuffer());check(bytes.length<=10_000_000&&response.headers.get('cache-control')?.includes('no-store'),'Response budget/no-store violated.');return {status:response.status,bytes,text:new TextDecoder('utf8',{fatal:true}).decode(bytes)}};
const get=async(route:string,role:Role='manager1')=>{const r=await call(route,role);check(r.status===200,'Authorized GET failed.');return parseM78Json(r.text,10_000_000)},scope1=async()=>decodeScope1Register(await get(root+'/scope1-inventory'),COMPANY),decoders:any={'corporate-inventories':decodeCorporateVersion,'stationary-natural-gas':decodeGasVersion,'mobile-diesel':decodeMobileVersion,'stationary-diesel':decodeGeneratorVersion,'controlled-fleet':decodeFleetVersion,'stationary-equipment':decodeStationaryVersion,'fugitive-sources':decodeFugitiveVersion,'fugitive-population':decodeFugitiveVersion,'process-screen':decodeScope1Version,'scope1-inventory':decodeScope1Version};const seen=new Set<string>();
const post=async(name:string,route:string,role:string,request:unknown,expected=201)=>{stage=name;check(expected===201&&posts<38&&!seen.has(name)&&['manager1','manager2'].includes(role),'Single-use successful recipe write required.');check(route===root+'/scope1-inventory'||route===root+'/process-screen'||new RegExp('^'+root+'/(corporate-inventories|stationary-natural-gas|mobile-diesel|stationary-diesel|controlled-fleet|stationary-equipment|fugitive-sources|fugitive-population|process-screen|scope1-inventory)/[a-f0-9-]{36}/(versions|reviews|reports)$').test(route),'Fixed recipe write route refused.');await append('post_intent',{name,route,role,expected,request});posts++;seen.add(name);const response=await call(route,role as Role,request);await append('post_outcome',{name,route,role,status:response.status,responseSha256:sha(response.bytes),byteLength:response.bytes.length});check(response.status===201,'Recipe POST refused; inspect frozen journal, never retry.');const raw:any=parseM78Json(response.text,10_000_000),family=route.slice(root.length+1).split('/')[0]!;let decoded:any;if(route.endsWith('/reviews')){let exact:unknown;if(family==='controlled-fleet'||family==='stationary-equipment'){const register=await (family==='controlled-fleet'?decodeFleetRegister:decodeStationaryRegister)(await get(root+'/'+family),COMPANY);check(route===root+'/'+family+'/'+register.rosterId+'/reviews','Exact retained roster identity mismatch.');exact=register}else exact=await decoders[family](await get(route.replace(/\/reviews$/,'/versions/'+raw.versionId)),COMPANY);check(same(m78RecipeRetainedReview(exact,raw.versionId,raw.id),raw),'Exact retained review mismatch.');decoded=raw}else if(route.endsWith('/reports')){decoded=await decodeScope1Report(raw,COMPANY);check(same(decoded,await decodeScope1Report(await get(route+'/'+raw.id),COMPANY)),'Exact retained report mismatch.');for(const [operation,value]of [['download',decoded.html],['snapshot',decoded.snapshotJson]]){const read=await call(route+'/'+raw.id+'/'+operation,'member');check(read.status===200&&read.text===value,'Report download mismatch.')}}else{decoded=await decoders[family](raw,COMPANY);const v=m78RecipeVersionRecord(decoded),base=route.endsWith('/versions')?route.slice(0,-9):route+'/'+(v.streamId??v.worksheetId??v.rosterId??v.inventoryId);const exact=await decoders[family](await get(base+'/versions/'+v.id),COMPANY);check(same(exact,decoded),'Exact retained version mismatch.')}await append('post_verified',{name,responseSha256:sha(response.bytes),decodedEnvelope:decoded});return decoded};
const final=await exerciseM78({root,accounts:Object.entries(input.actorIds).map(([role,id])=>({role,id})),scope1,post});check(posts===38&&final.process.versions.length===1&&final.inventory.versions.length===2&&final.process.reports.length===2&&final.inventory.reports.length===3,'Exact recipe closure counts changed.');check(final.reconciliation.status==='reconciled_bounded_synthetic'&&final.reconciliation.totals!==null&&final.inventory.versions.at(-1)?.review?.decision==='accepted_bounded_inventory'&&final.process.versions.at(-1)?.review?.decision==='accepted_bounded_process_screen','Final bounded acceptance failed.');const coverage=final.coverageVersion;for(const source of final.proof.sourceVersions)check(source.version.activity.binding.coverageVersionId===coverage.id&&source.version.review?.decision==='accepted_bounded_internal','Source binding/review incomplete.');for(const f of ['fleet','stationary','fugitive']as const)check((final.proof[f].version?.activity as {coverageVersionId?:string}|undefined)?.coverageVersionId===coverage.id&&final.proof[f].review?.decision==='accepted_bounded_reconciliation','Discovery binding/review incomplete.');for(const key of ['entities','facilities','sources']as const)check(same(baseline.coverageVersion.snapshot[key],coverage.snapshot[key]),'Corporate identities changed.');check(same(final,await decodeScope1Register(await get(root+'/scope1-inventory','member'),COMPANY)),'Final member readback mismatch.');const registerDecoders:any={'corporate-inventories':decodeCorporateRegister,'stationary-natural-gas':decodeGasRegister,'mobile-diesel':decodeMobileRegister,'controlled-fleet':decodeFleetRegister,'stationary-equipment':decodeStationaryRegister,'stationary-diesel':decodeGeneratorRegister,'fugitive-sources':decodeFugitiveRegister};for(const [path,decode]of Object.entries(registerDecoders))await (decode as any)(await get(root+'/'+path,'member'),COMPANY);const after=await m78RecipeRows(operator),retention=verifyM78RecipeOldRows(before,after);for(const suffix of ['requests','audit']){const delta=FAMILIES.reduce((n,f)=>n+(after[f+'_'+suffix]?.length??0)-(before[f+'_'+suffix]?.length??0),0);check(delta===38,'Exact recipe request/audit append count changed.');}check(same(beforeRoles,await roles(operator)),'Global role/membership state changed.');check(same(sourcePins,await m78RecipeSourcePins()),'Source changed during rehearsal.');await append('complete',{status:'m78_exact_recipe_native_passed',applicationPostRequests:posts,retention,baselineRowsSha256,finalRowsSha256:sha(canonical(after)),globalRolesAndMembershipsUnchanged:true,providerAuthSessionsCreated:0,final,scope1ReleaseReadiness:'incomplete',sourceDatabaseNotCreatedByRunner:true});return {status:'m78_exact_recipe_native_passed',database:input.database,applicationPostRequests:posts,retention,receiptSha256:previousSha256,providerAuthSessionsCreated:0,scope1ReleaseReadiness:'incomplete'};
}catch(error){if(journal)try{await append('failed',{stage,applicationPostRequests:posts,errorCategory:(error as any).code??'rehearsal_guard',retryAllowed:false})}catch{}throw error}finally{await journal?.close();await runtime?.close();await operator.close()}}
if(import.meta.main){try{const raw=await Bun.stdin.text();check(Buffer.byteLength(raw)<=200_000,'Bounded explicit input required.');console.log(JSON.stringify(await runM78Recipe(parseM78RecipeInput(parseM78Json(raw,200_000)))))}catch{console.log(JSON.stringify({status:'m78_recipe_rehearsal_failed',retryAllowed:false,sourceAndJournalNotReset:true}));process.exitCode=1}}

